using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Networking;
using CatCafePreview.Standalone;
namespace CatCafePreview {
 public sealed class StandaloneMissingConversationSmoke:MonoBehaviour {
  static int checks;
  static void Check(bool ok,string why){checks++;if(!ok)throw new Exception("Missing ADV: "+why);}
  static CafeResponse Send(LocalCafeBackend b,string kind,string cat=null,string choice=null,int slot=1){CafeResponse result=null;var c=new PythonShiftCommand{request_id=Guid.NewGuid().ToString("N"),instance_id=b.Simulation.State.instance_id,expected_revision=b.Simulation.State.revision,kind=kind,cat_id=cat,choice=choice,save_slot=slot,save_id=slot.ToString(),working_cats=new string[0]};var q=b.Request("/commands",JsonUtility.ToJson(c),r=>result=r);while(q.MoveNext()){}return result;}
  static void Good(LocalCafeBackend b,string k,string cat=null,string choice=null,int slot=1){var r=Send(b,k,cat,choice,slot);Check(r.result==UnityWebRequest.Result.Success,k+": "+r.error);}
  static CafeRules Rules(bool kittens){var r=JsonUtility.FromJson<CafeRules>(Resources.Load<TextAsset>("CatCafeStandalone/rules").text);r.starting_funds=30000;r.intake.day=r.regular_introduction.day=9999;r.growth.threshold=10000;r.store_events.probability=0;r.kitten_probability=kittens?1:0;return r;}
  static void Finish(LocalCafeBackend b,CafeMissingCase e,string phase){var p=CafeMissingDialogue.Progress(e,phase);if(p==null)return;p.node=CafeMissingDialogue.Lines(e,phase,"").Length;p.page_offset=0;CafeMissingDialogue.Finish(p);b.RememberViewedConversations();}
  static string Digest(LocalCafeBackend b)=>CafeReplayJournal.Digest(b.Simulation.State);
  static void Roundtrip(LocalCafeBackend b,int slot=1){string d=Digest(b);Good(b,"save_game",slot:slot);Good(b,"load_game",slot:slot);Check(d==Digest(b),"save/load gameplay");}
  static void Missing(LocalCafeBackend b,int count=1){foreach(var c in b.Simulation.State.cats.Take(count)){c.activity="missing";c.working=false;c.missing_remaining=2;c.kitten=b.Simulation.Rules.kitten_probability==1;}b.View();}
  public static int Run(string directory){checks=0;
   foreach(bool kittens in new[]{false,true}){
    string path=Path.Combine(directory,kittens?"kitten":"alone");var b=new LocalCafeBackend(path,Rules(kittens));Good(b,"new_game",choice:"free");Missing(b,2);var s=b.Simulation.State;var cases=s.missing_cases.ToArray();Check(cases.Length==2,"multiple legacy cases");Check(cases.All(e=>e.departed_day==0 && e.reason==null),"legacy cause fabricated");
    foreach(var e in cases){Check(b.BeginMissingConversation(e.id),"notice missing");Check(b.MissingPhase=="notice","notice phase");var p=b.MissingProgress;p.node=1;p.page_offset=2;Roundtrip(b);Check(b.MissingProgress.node==1 && b.MissingProgress.page_offset==2,"cursor lost");s=b.Simulation.State;e.notice=s.missing_cases.Single(x=>x.id==e.id).notice;Finish(b,s.missing_cases.Single(x=>x.id==e.id),"notice");}
    Check(!b.MissingBlocksProgress,"waiting blocks time");Check(b.View().missing_cats.All(v=>!v.kitten && v.cost==0),"early kitten leak");
    // Every cat absent: existing day_off route must remain available.
    foreach(var c in b.Simulation.State.cats){c.activity="missing";c.working=false;c.missing_remaining=2;c.kitten=kittens;}b.View();Check(b.View().day_off.can_select,"no working cats cannot rest");
    Good(b,"day_off");Check(b.Simulation.State.cats.All(c=>c.missing_remaining==1),"first rest schedule");Roundtrip(b,2);Good(b,"day_off");s=b.Simulation.State;Check(s.cats.All(c=>c.missing_remaining==0),"second rest schedule");Roundtrip(b,3);
    foreach(var e in b.Simulation.State.missing_cases.ToArray()){
     Check(b.BeginMissingConversation(e.id) && b.MissingPhase=="confirmation","return wait phase");Roundtrip(b,3);var v=b.View().missing_cats.Single(x=>x.choice==e.id);Check(v.kitten==kittens && v.can_resolve,"published return details");double funds=b.Simulation.State.funds;int cats=b.Simulation.State.cats.Count;Good(b,"resolve_missing",e.cat_id,e.id);var resolved=b.Simulation.State.missing_cases.Single(x=>x.id==e.id);Check(resolved.resolved_day>0 && resolved.cost==(kittens?b.Simulation.Rules.kitten_cost:0),"settlement record");Check(b.Simulation.State.funds==funds-resolved.cost && b.Simulation.State.cats.Count==cats,"fee or new kitten");var c=b.Simulation.State.cats.Single(x=>x.id==e.cat_id);Check(c.activity=="cafe" && !c.working && c.stamina==b.Simulation.MaxStamina(c.id),"return status");Check(b.MissingBlocksProgress,"unread result not pending");string d=Digest(b);Check(Send(b,"resolve_missing",e.cat_id,e.id).result!=UnityWebRequest.Result.Success && Digest(b)==d,"repeat confirmation");Check(Send(b,"day_off").result!=UnityWebRequest.Result.Success,"result bypass");Check(b.BeginMissingConversation(e.id) && b.MissingPhase=="result","result phase");b.MissingProgress.node=1;Roundtrip(b,4);Check(b.MissingProgress.node==1,"result restart");Finish(b,b.MissingCase,"result");Check(Digest(b)==d,"view changed gameplay");
    }
    Check(!b.MissingBlocksProgress,"results remain blocking");Check(b.Replays.Load().entries.Any(e=>e.conversation_id==CafeMissingDialogue.Id+".result" && e.branch_id==(kittens?"kitten":"alone")),"Extra missing");
    var first=b.Simulation.State.cats.First();int previous=b.Simulation.State.missing_cases.Count;first.activity="missing";first.missing_remaining=2;b.View();Check(b.Simulation.State.missing_cases.Count==previous+1 && b.Simulation.State.missing_cases.Select(e=>e.id).Distinct().Count()==previous+1,"repeat case merged");Roundtrip(b,5);
    // Legacy returned cats have no historical case and must not unlock old conversations.
    var old=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(path,"slot-4.json")));old.state.NormalizeJsonStrings();CafeDoublePrecision.Restore(old.state,old.double_bits);old.state.missing_cases=null;old.double_bits=CafeDoublePrecision.Capture(old.state);old.slot=6;old.missing_conversation_selected=null;old.missing_conversation_phase=null;File.WriteAllText(Path.Combine(path,"slot-6.json"),JsonUtility.ToJson(old));var legacy=new LocalCafeBackend(path,Rules(kittens));Good(legacy,"load_game",slot:6);Check(!legacy.Simulation.State.missing_cases.Any(e=>e.resolved_day>0),"invented legacy result");
   }
   // Production departure condition, with only fixture service state prepared.
   var actual=new LocalCafeBackend(Path.Combine(directory,"actual"),Rules(true));Good(actual,"new_game",choice:"free");var st=actual.Simulation.State;actual.Simulation.Execute("start_business");foreach(var c in st.cats){c.stress=100;c.service_ticks=1;}while(st.phase=="open")actual.Simulation.Execute("advance_business");actual.View();Check(st.missing_cases.Any(e=>e.reason=="stress" && e.departed_day==st.day),"production departure not recorded");
   // Cost ends business, result survives alongside outcome and growth display.
   var poor=new LocalCafeBackend(Path.Combine(directory,"poor"),Rules(true));Good(poor,"new_game",choice:"free");Missing(poor);var cat=poor.Simulation.State.cats.First();cat.missing_remaining=0;var ps=poor.Simulation.State;double delta=ps.funds-poor.Simulation.Rules.kitten_cost;ps.funds-=delta;ps.opening_funds-=delta;poor.View();var ev=ps.missing_cases.First();Good(poor,"resolve_missing",cat.id,ev.id);Check(ps.game_over=="funds" && poor.OutcomePending && poor.MissingResultPending,"funds ending priority");Roundtrip(poor,7);poor.BeginMissingConversation(ev.id);Finish(poor,poor.MissingCase,"result");Check(!poor.MissingResultPending && poor.OutcomePending,"outcome lost after result");
   // Different per-cat maxima, sickness/fatigue preserved, pending growth independent.
   var grown=new LocalCafeBackend(Path.Combine(directory,"grown"),Rules(false));Good(grown,"new_game",choice:"free");for(int day=0;day<20;day++)Good(grown,"day_off");var gc=grown.Simulation.State.cats.First();gc.health="sick";gc.recovery_remaining=2;gc.fatigue=55;Missing(grown);gc.missing_remaining=0;grown.View();var ge=grown.Simulation.State.missing_cases.First();Check(grown.View().missing_cats.First().max_stamina==110,"per-cat preview maximum");Good(grown,"resolve_missing",gc.id,ge.id);Check(gc.stamina==110 && gc.health=="sick" && gc.fatigue==55 && gc.cannot_continue,"per-cat recovery/preserved condition");Roundtrip(grown,8);Check(grown.MissingResultPending,"growth overlap lost");
   return checks;
  }
  string output;LocalCafeBackend backend;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--catcafe-missing-adv-check");if(i<0)return;var q=new GameObject("Missing ADV QA").AddComponent<StandaloneMissingConversationSmoke>();DontDestroyOnLoad(q);q.output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(q.output);Application.runInBackground=true;q.StartCoroutine(q.Guard());}
  System.Collections.IEnumerator Guard(){var p=Player();while(true){bool next;try{next=p.MoveNext();}catch(Exception e){File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);yield break;}if(!next)yield break;yield return p.Current;}}
  void Apply(PythonStateClient c){typeof(PythonStateClient).GetMethod("Accept",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(c,new object[]{backend.View()});}
  System.Collections.IEnumerator Player(){yield return new WaitForSecondsRealtime(1);int n=Run(Path.Combine(output,"backend"));if(Environment.GetCommandLineArgs().Contains("--missing-resume")){backend=new LocalCafeBackend(Path.Combine(output,"manual"),Rules(true));Good(backend,"load_game",slot:9);CafeBackends.UseLocal(backend);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var resumed=FindObjectOfType<PythonStateClient>();Apply(resumed);yield return null;Check(backend.MissingProgress.node==1 && resumed.GetComponent<MissingConversationPanel>().Showing,"separate process cursor");Screen.SetResolution(1024,768,false);File.WriteAllText(Path.Combine(output,"restart-result.txt"),"PASS: "+checks+" including persisted result");yield break;}backend=new LocalCafeBackend(Path.Combine(output,"manual"),Rules(true));Good(backend,"new_game",choice:"free");Missing(backend);CafeBackends.UseLocal(backend);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var client=FindObjectOfType<PythonStateClient>();Apply(client);yield return null;var ui=client.GetComponent<MissingConversationPanel>();Check(ui!=null && ui.Showing,"notice UI absent");ui.Close();client.GetComponent<PythonEventListPanel>().ShowMenu(4);yield return null;Check(ui.Showing,"list resume");var e=backend.MissingCase;Finish(backend,e,"notice");ui.Close();var cat=backend.Simulation.State.cats.First(c=>c.id==e.cat_id);cat.missing_remaining=0;Apply(client);yield return null;Check(ui.Showing && backend.MissingPhase=="confirmation","confirmation UI absent");ui.Close();client.GetComponent<PythonMissingPanel>().Confirm();client.GetComponent<PythonMissingPanel>().Confirm();yield return new WaitForSecondsRealtime(1);Check(backend.MissingResultPending && backend.MissingCase.resolved_day>0,"confirm UI absent");Apply(client);yield return null;Check(ui.Showing && backend.MissingPhase=="result","result UI absent");backend.MissingProgress.node=1;Good(backend,"save_game",slot:9);var restarted=new LocalCafeBackend(Path.Combine(output,"manual"),Rules(true));Good(restarted,"load_game",slot:9);backend=restarted;CafeBackends.UseLocal(backend);Apply(client);yield return null;Check(backend.MissingProgress.node==1 && ui.Showing,"UI save restore");
   // Ending must wait for the exact unread result, then become available.
   backend=new LocalCafeBackend(Path.Combine(output,"backend/poor"),Rules(true));Good(backend,"load_game",slot:7);CafeBackends.UseLocal(backend);Apply(client);yield return null;ui=client.GetComponent<MissingConversationPanel>();Check(ui.Showing && !client.GetComponent<OutcomeConversationPanel>().Showing,"ending covered missing result");var growth=backend.View();growth.growth_choices=new[]{new PythonGrowthChoice()};client.GetComponent<PythonGrowthPanel>().Apply(growth);Check(!client.GetComponent<PythonGrowthPanel>().panel.activeSelf,"growth covered result");backend.MissingProgress.node=3;backend.MissingProgress.page_offset=0;Apply(client);yield return null;ui.Next();yield return null;Check(!backend.MissingResultPending && client.GetComponent<OutcomeConversationPanel>().Showing,"ending not resumed");
   // Extra runs only fixed text and never sends a settlement command.
   UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();foreach(bool k in new[]{false,true})backend.Replays.Merge(new LocalCafeBackend(Path.Combine(output,k?"backend/kitten":"backend/alone"),Rules(k)).Replays.Load().entries);extra.Open();yield return null;string fixedState=JsonUtility.ToJson(backend.Simulation.State);foreach(string branch in new[]{"kitten","alone"}){extra.OpenReplay(CafeMissingDialogue.Id+".result/"+branch);yield return null;Check(extra.Replay.Showing,"Extra return unavailable");extra.Replay.Answer(true);extra.Replay.Next();extra.Replay.Close();}Check(fixedState==JsonUtility.ToJson(backend.Simulation.State),"Extra mutated missing state");extra.Hide();
   backend=new LocalCafeBackend(Path.Combine(output,"manual"),Rules(true));Good(backend,"load_game",slot:9);CafeBackends.UseLocal(backend);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);client=FindObjectOfType<PythonStateClient>();Apply(client);yield return null;
   // Leave final result midway for native interaction; real second process can load the same slot.
   Screen.SetResolution(1280,800,false);File.WriteAllText(Path.Combine(output,"result.txt"),"PASS: "+checks+" missing ADV; backend="+n);ScreenCapture.CaptureScreenshot(Path.Combine(output,"manual-ready.png"));
  }
 }
}
